import React, { useContext } from 'react';
import { CartContext } from '../context/CartContext';
import { FiTrash2, FiPlus, FiMinus } from 'react-icons/fi';
import './Cart.css';

const Cart = () => {
  const { cart, removeFromCart, updateQuantity, totalPrice, clearCart } = useContext(CartContext);

  const sendToWhatsApp = () => {
    const phoneNumber = '77001234567'; // Замени на свой номер
    let message = '🛍 *Новый заказ:*\n\n';
    
    cart.forEach((item, index) => {
      message += `${index + 1}. *${item.name}*\n`;
      
      // Если это кастомный букет, добавляем детали в сообщение
      if (item.type === 'bouquet') {
        message += `   💐 Состав: ${item.flowers.map(f => `${f.name} (x${f.quantity})`).join(', ')}\n`;
        message += `   🎀 Упаковка: ${item.package.name}\n`;
        message += `   🎗 Лента: ${item.ribbon.name}\n`;
        if (item.card.text) {
          message += `   ✉️ Открытка: "${item.card.text}" ${item.card.signature ? `(от: ${item.card.signature})` : ''}\n`;
        }
        message += `   📍 Адрес: ${item.deliveryAddress.street}, д.${item.deliveryAddress.house}${item.deliveryAddress.apartment ? `, кв.${item.deliveryAddress.apartment}` : ''}\n`;
      }

      message += `   Count: ${item.quantity} x ${item.price.toLocaleString()} ₸ = ${(item.quantity * item.price).toLocaleString()} ₸\n\n`;
    });
    
    message += `*ИТОГО: ${totalPrice.toLocaleString()} ₸*`;
    
    const encoded = encodeURIComponent(message);
    window.open(`https://wa.me/${phoneNumber}?text=${encoded}`, '_blank');
  };

  if (cart.length === 0) {
    return (
      <div className="empty-cart">
        <h2>🛒 Корзина пуста</h2>
        <p>Добавьте цветы из нашего каталога</p>
      </div>
    );
  }

  return (
    <div className="cart-container">
      <h2 className="cart-title">Корзина</h2>
      
      <div className="cart-items">
        {cart.map(item => (
          <div key={item.id} className="cart-item">
            <img src={item.imageUrl} alt={item.name} className="cart-item-image" />
            
            <div className="cart-item-info">
              <h3 className="cart-item-name">{item.name}</h3>
              <p className="cart-item-price">{item.price.toLocaleString()} ₸</p>

              {/* Секция для кастомного букета */}
              {item.type === 'bouquet' && (
                <div className="bouquet-details">
                  <p><strong>Состав:</strong></p>
                  <ul className="flowers-list">
                    {item.flowers.map((f, idx) => (
                      <li key={idx}>{f.name} x{f.quantity}</li>
                    ))}
                  </ul>
                  <div className="extra-info">
                    <p><span>Упаковка:</span> {item.package.name}</p>
                    <p><span>Лента:</span> {item.ribbon.name}</p>
                    {item.card.text && (
                      <p><span>Открытка:</span> "{item.card.text}" {item.card.signature && `(от ${item.card.signature})`}</p>
                    )}
                    <p className="delivery-address">
                      <strong>Адрес:</strong> {item.deliveryAddress.street}, д.{item.deliveryAddress.house}
                      {item.deliveryAddress.apartment && `, кв.${item.deliveryAddress.apartment}`}
                    </p>
                  </div>
                </div>
              )}
            </div>
            
            <div className="cart-item-quantity">
              <button 
                onClick={() => updateQuantity(item.id, item.quantity - 1)}
                className="quantity-btn"
              >
                <FiMinus />
              </button>
              <span className="quantity">{item.quantity}</span>
              <button 
                onClick={() => updateQuantity(item.id, item.quantity + 1)}
                className="quantity-btn"
              >
                <FiPlus />
              </button>
            </div>
            
            <div className="cart-item-total">
              {(item.price * item.quantity).toLocaleString()} ₸
            </div>
            
            <button 
              onClick={() => removeFromCart(item.id)}
              className="remove-btn"
            >
              <FiTrash2 />
            </button>
          </div>
        ))}
      </div>
      
      <div className="cart-summary">
        <div className="cart-total">
          <span>Итого:</span>
          <span className="total-price">{totalPrice.toLocaleString()} ₸</span>
        </div>
        
        <div className="cart-actions">
          <button onClick={clearCart} className="clear-btn">
            Очистить корзину
          </button>
          <button onClick={sendToWhatsApp} className="whatsapp-btn">
            📱 Оформить заказ
          </button>
        </div>
      </div>
    </div>
  );
};

export default Cart;